window.APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH04 = [
{id:"P6-G-B04-001",level:"P6",topic:"Subject-Verb Agreement",skill:"agreement with intervening phrases",question:"The box of old photographs ___ under the bed.",options:["is","are","were","have"],answer:"is",explanation:"The subject is 'box', which is singular; 'of old photographs' does not change the subject.",difficulty:3,misconception:"matching the verb with the nearest plural noun"},
{id:"P6-G-B04-002",level:"P6",topic:"Tenses and Aspect",skill:"past perfect sequence",question:"By the time the bus arrived, we ___ for twenty minutes.",options:["had waited","wait","have waited","will wait"],answer:"had waited",explanation:"The past perfect shows an action completed before another past event.",difficulty:4,misconception:"using simple past for the earlier completed action"},
{id:"P6-G-B04-003",level:"P6",topic:"Verb Forms",skill:"third-person singular",question:"My brother usually ___ his homework before dinner.",options:["finishes","finish","finishing","finished"],answer:"finishes",explanation:"A singular third-person subject in the present simple takes the -s form.",difficulty:2,misconception:"omitting the third-person singular ending"},
{id:"P6-G-B04-004",level:"P6",topic:"Articles and Determiners",skill:"article before specific noun",question:"Please return ___ book that you borrowed yesterday.",options:["the","a","an","no article"],answer:"the",explanation:"The noun is specific because it is identified by 'that you borrowed yesterday'.",difficulty:3,misconception:"using a when the noun is already identified"},
{id:"P6-G-B04-005",level:"P6",topic:"Pronouns",skill:"reflexive pronouns",question:"Sarah made the model all by ___.",options:["herself","her","she","hers"],answer:"herself",explanation:"A reflexive pronoun is needed because Sarah performed the action herself.",difficulty:3,misconception:"choosing an object or possessive pronoun"},
{id:"P6-G-B04-006",level:"P6",topic:"Prepositions",skill:"time prepositions",question:"The school concert begins ___ 7.30 p.m.",options:["at","on","in","by"],answer:"at",explanation:"Use 'at' with a specific clock time.",difficulty:2,misconception:"confusing at, on and in"},
{id:"P6-G-B04-007",level:"P6",topic:"Conjunctions",skill:"contrast connector",question:"___ it was raining, the pupils continued their training.",options:["Although","Because","So","Unless"],answer:"Although",explanation:"Although introduces a contrast between rain and continuing training.",difficulty:3,misconception:"choosing a cause connector for a contrast relationship"},
{id:"P6-G-B04-008",level:"P6",topic:"Adjectives and Adverbs",skill:"adverb modification",question:"The athlete ran ___ to catch the bus.",options:["quickly","quick","quicker","quickness"],answer:"quickly",explanation:"An adverb modifies the verb 'ran'.",difficulty:2,misconception:"using an adjective where an adverb is required"},
{id:"P6-G-B04-009",level:"P6",topic:"Comparatives and Superlatives",skill:"superlative form",question:"Of the three routes, this one is the ___.",options:["shortest","shorter","most short","more short"],answer:"shortest",explanation:"The superlative compares one item with all three routes.",difficulty:2,misconception:"using comparative instead of superlative"},
{id:"P6-G-B04-010",level:"P6",topic:"Countable and Uncountable Nouns",skill:"uncountable noun",question:"We need some ___ for the science experiment.",options:["equipment","equipments","an equipment","equipmentses"],answer:"equipment",explanation:"Equipment is generally uncountable and does not take a plural -s in standard English.",difficulty:3,misconception:"adding a plural ending to an uncountable noun"},
{id:"P6-G-B04-011",level:"P6",topic:"Quantifiers",skill:"many versus much",question:"How ___ water should we bring for the hike?",options:["much","many","few","several"],answer:"much",explanation:"Water is uncountable, so 'much' is appropriate.",difficulty:2,misconception:"using many with an uncountable noun"},
{id:"P6-G-B04-012",level:"P6",topic:"Gerunds and Infinitives",skill:"verb followed by gerund",question:"Lena enjoys ___ mystery stories.",options:["reading","to read","read","reads"],answer:"reading",explanation:"Enjoy is followed by a gerund (-ing form).",difficulty:3,misconception:"using infinitive after enjoy"},
{id:"P6-G-B04-013",level:"P6",topic:"Phrasal Verbs",skill:"separable phrasal verb",question:"Please ___ the lights before leaving the room.",options:["turn off","turn on","look after","look for"],answer:"turn off",explanation:"The context requires the phrasal verb meaning stop the lights from being on.",difficulty:2,misconception:"choosing a phrasal verb from an unrelated meaning"},
{id:"P6-G-B04-014",level:"P6",topic:"Relative Clauses",skill:"who for people",question:"The teacher ___ helped us is very patient.",options:["who","which","where","whose"],answer:"who",explanation:"Who is used as the relative pronoun for a person in this clause.",difficulty:2,misconception:"using which for a person"},
{id:"P6-G-B04-015",level:"P6",topic:"Conditionals",skill:"first conditional",question:"If you finish your work early, you ___ join the game.",options:["can","could have","had","would have"],answer:"can",explanation:"A real possible condition can be followed by can in the result clause.",difficulty:3,misconception:"forcing a past conditional structure"},
{id:"P6-G-B04-016",level:"P6",topic:"Passive Voice",skill:"present passive",question:"The classroom ___ every afternoon.",options:["is cleaned","cleans","cleaned it","is cleaning"],answer:"is cleaned",explanation:"The classroom receives the action, so the present passive is required.",difficulty:3,misconception:"using active voice when the subject receives the action"},
{id:"P6-G-B04-017",level:"P6",topic:"Reported Speech",skill:"reported statement",question:"Mia said, “I am tired.” Which is correct?",options:["Mia said that she was tired.","Mia said that I am tired.","Mia said that she is tired yesterday.","Mia said that tired she was."],answer:"Mia said that she was tired.",explanation:"In a past reporting context, 'am' changes to 'was' and 'I' changes to 'she'.",difficulty:4,misconception:"failing to change pronouns and tense"},
{id:"P6-G-B04-018",level:"P6",topic:"Sentence Structure",skill:"parallel structure",question:"The club teaches pupils to plan, to build and ___.",options:["to test","testing","tests","tested"],answer:"to test",explanation:"The three infinitive phrases should be parallel: to plan, to build and to test.",difficulty:4,misconception:"breaking grammatical parallelism"},
{id:"P6-G-B04-019",level:"P6",topic:"Cohesive Devices",skill:"result connector",question:"The road was flooded, ___ the match was postponed.",options:["so","although","unless","while"],answer:"so",explanation:"So introduces the result of the road being flooded.",difficulty:2,misconception:"choosing a contrast or condition connector"},
{id:"P6-G-B04-020",level:"P6",topic:"Editing",skill:"error diagnosis",question:"Which sentence is correct?",options:["Neither of the answers is correct.","Neither of the answers are correct.","Neither answers is correct.","Neither of the answer are correct."],answer:"Neither of the answers is correct.",explanation:"Neither is singular in this construction, and 'answers' is correctly plural after 'of the'.",difficulty:4,misconception:"matching the verb with the plural noun instead of the main subject"}
];